 function stop(id){const r=runs.get(id);if(!r)return;cancelAnimationFrame(r.frame);runs.delete(id);$(id+'-play').textContent=r.label;$(id+'-play').setAttribute('aria-pressed','false');r.save();}
 function line(p,data,color,dash='',step=false){p.layer.append('path').datum(data).attr('class','population-data-line').attr('d',d3.line().curve(step?d3.curveStepAfter:d3.curveLinear).x(d=>p.x(d.x)).y(d=>p.y(d.y))).attr('fill','none').attr('stroke',color).attr('stroke-width',2).attr('stroke-dasharray',dash);}
